  function syncImageColorOptions(){
    const select=$('#imageColor');if(!select||!editorState)return;
    const flags=modeFlags(categoryById($('#fCategory').value)),current=select.value;
    const names=[...new Set(editorState.rows.map(variantColorName).filter(Boolean))];
    select.replaceChildren();
    if(!flags.color){select.append(new Option('Imagen general',''));select.disabled=false;setText('#imageColorHelp','Estas fotos corresponden al producto completo.')}
    else if(!names.length){select.append(new Option('Primero escribe un color',''));select.disabled=true;setText('#imageColorHelp','Escribe Color o Nombre para el cliente en una variante para asociar sus fotos.')}
    else{
      for(const name of names){const row=editorState.rows.find(row=>variantColorName(row)===name);select.append(new Option(row.colorDisplay?.trim()||name,name))}
      if(names.includes(current))select.value=current;
      select.disabled=false;setText('#imageColorHelp','Selecciona el color que aparece en estas fotos. Se mostrará al elegirlo en la tienda.');
    }
    $('#uploadImages').disabled=flags.color&&!names.length;
    $('#imageFiles').disabled=flags.color&&!names.length;
    $('#imageManager').hidden=false;
  }

  function renderPreview(){if(!editorState)return;const root=$('#editorPreview');root.replaceChildren();const data=generalData(),img=editorState.images.find(i=>i.is_cover)||editorState.images[0],image=document.createElement('img');image.src=imageUrl(img)||'/assets/images/logo.webp';image.alt='Vista previa';const body=document.createElement('div'),brand=document.createElement('small'),h=document.createElement('h3'),pr=document.createElement('strong'),meta=document.createElement('p');brand.textContent=[data.brand,categoryById(data.category_id)?.name].filter(Boolean).join(' · ');h.textContent=data.name||'Nombre del producto';pr.textContent=data.price==null?'Consultar precio':money(data.price);const vals=Object.entries(data.attributes||{}).map(([k,v])=>{const a=attrsForCategory(data.category_id,'product').find(x=>x.key===k);return a?`${a.label}: ${Array.isArray(v)?v.join(', '):v}`:''}).filter(Boolean);meta.textContent=vals.join(' · ')||'Sin atributos adicionales';body.append(brand,h,pr,meta);root.append(image,body)}
