  async function renderImages(){const root=$('#imageGrid');if(!root||!editorState)return;root.replaceChildren();editorState.images.sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).forEach((img,idx)=>{const card=document.createElement('article');card.className='image-item';card.draggable=true;card.dataset.id=img.id;const im=document.createElement('img');im.src=imageUrl(img);im.alt=img.alt||'';const s=document.createElement('small');s.textContent=img.alt||img.storage_path||'Imagen';const acts=document.createElement('div');acts.className='image-actions';acts.append(btn(img.is_cover?'Portada ✓':'Hacer portada',()=>makeCover(img)),btn('Eliminar',()=>deleteImage(img)));card.append(im,s,acts);card.addEventListener('dragstart',()=>{card.classList.add('dragging');window._dragImageId=img.id});card.addEventListener('dragend',()=>card.classList.remove('dragging'));card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',async e=>{e.preventDefault();const from=editorState.images.findIndex(x=>x.id===window._dragImageId),to=idx;if(from<0||from===to)return;const [m]=editorState.images.splice(from,1);editorState.images.splice(to,0,m);await saveImageOrder();renderImages()});root.append(card)})}
  function imageColorKey(image){return image.pending?(image.colorName||''):variantColorName(editorState.rows.find(row=>row.colorId===image.color_id)||{})}
  function releaseLocalImages(){for(const image of editorState?.images||[])if(image.localUrl)URL.revokeObjectURL(image.localUrl)}
  let pendingImageTask=null;
  function stageSelectedImages(){if(!pendingImageTask)pendingImageTask=uploadImages().finally(()=>{pendingImageTask=null});return pendingImageTask}
  async function uploadImages(){
    const files=[...$('#imageFiles').files];if(!files.length)return;
    const flags=modeFlags(categoryById($('#fCategory').value)),colorName=flags.color?$('#imageColor').value:'';
    if(flags.color&&!colorName)throw new Error('Escribe el color antes de agregar sus fotos.');
    const queued=[];setText('#uploadStatus','Preparando fotos…');
    try{for(const file of files){const prepared=await window.BattingImages.prepare(file);queued.push({id:uuid(),pending:true,prepared,localUrl:URL.createObjectURL(prepared.full),colorName,color_id:editorState.rows.find(r=>variantColorName(r)===colorName)?.colorId||null,alt:file.name,sort_order:editorState.images.length+queued.length,is_cover:!editorState.images.concat(queued).some(i=>imageColorKey(i)===colorName&&i.active!==false),active:true})}}
    catch(error){queued.forEach(image=>URL.revokeObjectURL(image.localUrl));setText('#uploadStatus','No se agregaron las fotos. Revisa el archivo.');throw error}
    editorState.images.push(...queued);$('#imageFiles').value='';setText('#uploadStatus','Fotos listas. Se subirán al publicar.');renderImages();renderPreview();
  }
  async function persistPendingImages(){
    for(let index=0;index<editorState.images.length;index++){
      const image=editorState.images[index];if(!image.pending)continue;
      const colorId=image.colorName?editorState.rows.find(r=>variantColorName(r)===image.colorName)?.colorId:null;
      if(image.colorName&&!colorId)throw new Error('Revisa el color asociado a la foto antes de publicar.');
      const stem=editorState.productId+'/'+image.id,path=stem+'.webp',thumbnailPath=stem+'.thumb.webp',ogPath=stem+'.og.jpg',uploaded=[];
      try{
        for(const [target,content,type] of [[path,image.prepared.full,'image/webp'],[thumbnailPath,image.prepared.thumbnail,'image/webp'],[ogPath,image.prepared.jpg,'image/jpeg']]){const {error}=await sb.storage.from('product-images').upload(target,content,{cacheControl:'31536000',upsert:false,contentType:type});if(error)throw error;uploaded.push(target)}
        const {data:row,error}=await sb.from('product_images').insert({product_id:editorState.productId,color_id:colorId||null,storage_path:path,thumbnail_path:thumbnailPath,og_storage_path:ogPath,width:image.prepared.width,height:image.prepared.height,alt:$('#fName').value+(image.colorName?' - '+image.colorName:''),sort_order:index,is_cover:image.is_cover,active:true}).select().single();if(error)throw error;
        URL.revokeObjectURL(image.localUrl);editorState.images[index]=row;
      }catch(error){if(uploaded.length)await sb.storage.from('product-images').remove(uploaded);throw error}
    }
    setText('#uploadStatus','Fotos guardadas.');
  }
  async function makeCover(img){
    for(const image of editorState.images.filter(image=>imageColorKey(image)===imageColorKey(img))){
      const selected=image.id===img.id;
      if(!image.pending){const {error}=await sb.from('product_images').update({is_cover:selected}).eq('id',image.id);if(error)return notify(error.message,{kind:'error'})}
      image.is_cover=selected;
    }
    renderImages();renderPreview();
  }
  async function deleteImage(img){if(!await askConfirm('¿Eliminar esta imagen?',{title:'Eliminar imagen',danger:true}))return;if(img.pending){URL.revokeObjectURL(img.localUrl);editorState.images=editorState.images.filter(i=>i.id!==img.id);renderImages();renderPreview();return}if(img.storage_path){const {error}=await sb.storage.from('product-images').remove([img.storage_path,img.thumbnail_path,img.og_storage_path].filter(Boolean));if(error)return notify(error.message,{kind:'error'})}const {error}=await sb.from('product_images').delete().eq('id',img.id);if(error)return notify(error.message,{kind:'error'});editorState.images=editorState.images.filter(i=>i.id!==img.id);await saveImageOrder();renderImages();renderPreview()}
  async function saveImageOrder(){for(let i=0;i<editorState.images.length;i++){editorState.images[i].sort_order=i;if(editorState.images[i].pending)continue;const {error}=await sb.from('product_images').update({sort_order:i}).eq('id',editorState.images[i].id);if(error)throw error}}

  async function applyBulkPrice(){if(!selected.size)return notify('Selecciona al menos un producto.',{kind:'error'});const mode=$('#bulkMode').value,raw=$('#bulkValue').value.trim();if(raw==='')return notify('Escribe un valor.',{kind:'error'});const val=Number(raw);if(!Number.isFinite(val))return notify('Valor inválido.',{kind:'error'});if(mode==='set'&&val<=0)return notify('El precio debe ser mayor que $0.',{kind:'error'});if(mode==='percent'&&(val===0||val<=-100))return notify('Porcentaje inválido.',{kind:'error'});if(!await askConfirm(`¿Aplicar cambio a ${selected.size} producto(s)?`))return;try{if(mode==='set'){const {error}=await sb.from('products').update({price:Number(val.toFixed(2))}).in('id',[...selected]);if(error)throw error}else{const list=products.filter(p=>selected.has(p.id));if(list.some(p=>!Number.isFinite(Number(p.price))||Number(p.price)<=0))throw new Error('No se puede aplicar porcentaje a productos sin precio.');for(const p of list){const next=Number(p.price)*(1+val/100);if(next<=0)throw new Error(`${p.name} quedaría en $0 o menos.`);const {error}=await sb.from('products').update({price:Number(next.toFixed(2))}).eq('id',p.id);if(error)throw error}}$('#bulkValue').value='';selected.clear();await loadProducts();notify('Precios actualizados.',{kind:'success'})}catch(e){notify(e.message,{kind:'error',timeout:6000})}}

