  function parseCsv(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'){if(quote&&next==='"'){cell+='"';i++}else quote=!quote}else if(ch===','&&!quote){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quote){if(ch==='\r'&&next==='\n')i++;row.push(cell);cell='';if(row.some(x=>x!==''))rows.push(row);row=[]}else cell+=ch}row.push(cell);if(row.some(x=>x!==''))rows.push(row);if(rows.length<2)return[];if(quote)throw new Error('CSV con comillas sin cerrar.');if(rows.length>5001)throw new Error('CSV: máximo 5000 filas.');const headers=rows[0].map(h=>h.trim());if(new Set(headers).size!==headers.length||headers.some(h=>!h||h.length>100))throw new Error('Cabeceras CSV inválidas o duplicadas.');if(rows.slice(1).some(r=>r.length!==headers.length))throw new Error('CSV con número de columnas inconsistente.');return rows.slice(1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()]))) }
